import { act, screen, waitFor, within } from "@testing-library/react";
import { userEvent } from "@testing-library/user-event";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { Check } from "../Icon";
import { renderWithProviders } from "../tests/utils";
import type { ShowToastOptions } from "../types/toast";
import { Toaster } from "./Toaster";
import { toaster } from "./toasterInstance";

function renderToaster() {
  renderWithProviders(<Toaster />);
}

async function showToast(options: ShowToastOptions) {
  act(() => {
    toaster.create(options);
  });
  await waitFor(() => {
    expect(screen.getByRole("status")).toBeInTheDocument();
  });
}

function getToastRoot() {
  return screen.getByRole("status");
}

function queryWithinToast(selector: string) {
  return getToastRoot().querySelector(selector);
}

describe("Toaster", () => {
  beforeEach(() => {
    renderToaster();
  });

  afterEach(() => {
    act(() => {
      toaster.remove();
    });
  });

  describe("mount", () => {
    it("renders the toaster container", () => {
      expect(screen.getByTestId("toaster")).toBeInTheDocument();
    });
  });

  describe("single-line content", () => {
    it.each([
      {
        field: "title",
        options: { title: "Info title", type: "info" as const },
        text: "Info title",
      },
      {
        field: "description",
        options: { description: "Info description ONLY", type: "info" as const },
        text: "Info description ONLY",
      },
    ])("renders $field-only toast as description style", async ({ options, text }) => {
      await showToast(options);

      expect(screen.getByText(text)).toBeInTheDocument();
      expect(screen.queryByRole("heading", { name: text })).not.toBeInTheDocument();
      expect(queryWithinToast('[data-part="description"]')).toHaveTextContent(text);
      expect(queryWithinToast('[data-part="title"]')).not.toBeInTheDocument();
    });
  });

  describe("dual-line content", () => {
    it("renders title as heading and description below", async () => {
      await showToast({
        title: "Error title",
        description: "Error description",
        type: "error",
      });

      expect(screen.getByRole("heading", { name: "Error title" })).toBeInTheDocument();
      expect(screen.getByText("Error description")).toBeInTheDocument();
      expect(queryWithinToast('[data-part="title"]')).toHaveTextContent("Error title");
      expect(queryWithinToast('[data-part="description"]')).toHaveTextContent("Error description");
    });
  });

  describe("icon", () => {
    it("renders default circle-info icon", async () => {
      await showToast({ title: "Info title", type: "info" });

      expect(within(getToastRoot()).getByRole("img", { hidden: true })).toHaveAttribute(
        "data-icon",
        "circle-info",
      );
    });

    it("renders default circle-check icon for success", async () => {
      await showToast({ title: "Success title", type: "success" });

      expect(within(getToastRoot()).getByRole("img", { hidden: true })).toHaveAttribute(
        "data-icon",
        "circle-check",
      );
    });

    it("hides icon when meta.iconStart is false", async () => {
      await showToast({
        description: "No icon",
        type: "info",
        meta: { iconStart: false },
      });

      expect(within(getToastRoot()).queryByRole("img", { hidden: true })).not.toBeInTheDocument();
    });

    it("renders custom icon from meta.icon", async () => {
      await showToast({
        title: "Success",
        type: "success",
        meta: { icon: Check },
      });

      expect(within(getToastRoot()).getByRole("img", { hidden: true })).toHaveAttribute(
        "data-icon",
        "check",
      );
    });
  });

  describe("actions", () => {
    it("renders close trigger by default", async () => {
      await showToast({ title: "Closable", type: "info" });

      expect(queryWithinToast('[data-part="close-trigger"]')).toBeInTheDocument();
    });

    it("hides close trigger when closable is false", async () => {
      await showToast({
        description: "Not closable",
        type: "info",
        closable: false,
      });

      expect(queryWithinToast('[data-part="close-trigger"]')).not.toBeInTheDocument();
    });

    it("calls action onClick when action trigger is clicked", async () => {
      const user = userEvent.setup();
      const onClick = vi.fn();

      await showToast({
        title: "With action",
        type: "info",
        action: { label: "Undo", onClick },
      });

      await user.click(screen.getByRole("button", { name: "Undo" }));

      expect(onClick).toHaveBeenCalledOnce();
    });

    it("dismisses toast when close trigger is clicked", async () => {
      vi.useFakeTimers({ shouldAdvanceTime: true });
      const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });

      try {
        await showToast({ title: "Dismiss me", type: "info" });

        const closeTrigger = queryWithinToast('[data-part="close-trigger"]');
        expect(closeTrigger).toBeInTheDocument();

        await user.click(closeTrigger as HTMLElement);

        await waitFor(() => {
          expect(getToastRoot()).toHaveAttribute("data-state", "closed");
        });

        await act(async () => {
          await vi.advanceTimersByTimeAsync(500);
        });

        expect(screen.queryByRole("status")).not.toBeInTheDocument();
      } finally {
        vi.useRealTimers();
      }
    });
  });
});
